public:
    int minimumTime(vector<int>& nums1, vector<int>& nums2, int x) {
        int n = nums1.size();
        vector<pair<int, int>> pairs(n);
        for (int i = 0; i < n; ++i) pairs[i] = {nums2[i], nums1[i]};
        sort(pairs.begin(), pairs.end());
        vector<long long> dp(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            int b = pairs[i].first, a = pairs[i].second;
            for (int j = n; j >= 1; --j) {
                dp[j] = max(dp[j], dp[j - 1] + a + 1LL * b * j);
            }
        }
        long long s1 = 0, s2 = 0;
        for (int v : nums1) s1 += v;
        for (int v : nums2) s2 += v;
        for (int t = 0; t <= n; ++t) {
            if (s1 + 1LL * t * s2 - dp[t] <= x) return t;
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minimumTime(List<Integer> nums1, List<Integer> nums2, int x) {
        int n = nums1.size();
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums2.get(i);
            pairs[i][1] = nums1.get(i);
        }
        Arrays.sort(pairs, (a, b) -> Integer.compare(a[0], b[0]));
        long[] dp = new long[n + 1];
        for (int i = 0; i < n; i++) {
            int b = pairs[i][0], a = pairs[i][1];
            for (int j = n; j >= 1; j--) {
                dp[j] = Math.max(dp[j], dp[j - 1] + a + (long) b * j);
            }
        }
        long s1 = 0, s2 = 0;
        for (int v : nums1) s1 += v;
        for (int v : nums2) s2 += v;
        for (int t = 0; t <= n; t++) {
            if (s1 + (long) t * s2 - dp[t] <= x) return t;
        }
        return -1;
    }
}

/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @param {number} x
 * @return {number}
 */
var minimumTime = function(nums1, nums2, x) {
    const n = nums1.length;
    const pairs = [];
    for (let i = 0; i < n; i++) pairs.push([nums2[i], nums1[i]]);
    pairs.sort((a, b) => a[0] - b[0]);
    const dp = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        const [b, a] = pairs[i];
        for (let j = n; j >= 1; j--) {
            dp[j] = Math.max(dp[j], dp[j - 1] + a + b * j);
        }
    }
    const s1 = nums1.reduce((acc, v) => acc + v, 0);
    const s2 = nums2.reduce((acc, v) => acc + v, 0);
    for (let t = 0; t <= n; t++) {
        if (s1 + t * s2 - dp[t] <= x) return t;
    }
    return -1;
};
